def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from opponents (immediate reaction)
    prev_bids = []
    high_bid = 0.0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                b = None
        if b is not None:
            prev_bids.append(b)
            if b > high_bid:
                high_bid = b

    # Identify aggressive opponent(s) from yesterday
    # Cindy-like pattern: high average/max bids and survival.
    aggressive = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            b = float(b)
        except Exception:
            continue
        # Use yesterday bid as proxy for aggressiveness
        if b >= DAILY_SALARY * 1.1:  # ~99
            aggressive.append(b)

    # Base bid: target to secure water when supply is modest.
    # Supply is between 15 and 25; with our requirement 9, 2 units likely enough.
    # We approximate units needed by ceiling(supply / WATER_REQ)?? Actually allocation is per unit bid.
    # Use supply to scale aggressiveness.
    supply_level = (float(supply) - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1

    # If we are in trouble, bid harder.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Compute a conservative ceiling to avoid overpaying against Cindy.
    # If Cindy was bidding high, we try to slightly undercut her typical peak.
    # Use high_bid as observed maximum yesterday.
    if prev_bids:
        # Underbid strategy: aim at 70% of max observed if aggressive, else around 60% of max.
        if aggressive:
            target = max(DAILY_SALARY * (0.85 + 0.1 * (1.0 - supply_level)), high_bid * 0.75)
        else:
            target = max(DAILY_SALARY * (0.7 + 0.2 * (1.0 - supply_level)), high_bid * 0.6)
    else:
        target = DAILY_SALARY * (0.6 + 0.2 * (1.0 - supply_level))

    # Urgency adjustments
    if hp <= 2.0:
        target *= 1.15
    elif hp <= 4.0:
        target *= 1.05

    # If we've already gone some days without water, increase bid to avoid death spiral.
    if no_water_days >= 2:
        target *= 1.12

    # Safety: do not bid more than budget or too close to total budget.
    # Also, if budget is low, scale down.
    if budget <= 0:
        return 0.0

    # Keep bid below a hard cap derived from budget and salary.
    hard_cap = min(budget, DAILY_SALARY * 1.2)
    bid = min(target, hard_cap)

    # If supply is high, we can bid lower; if low, bid higher.
    if supply_level > 0.6:
        bid *= 0.9
    elif supply_level < 0.3:
        bid *= 1.05

    # Final clamp
    if bid < 0:
        bid = 0.0
    return float(min(bid, budget))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    # In this specific scenario (WATER_REQ=13, supply_range=[15,25]), only 1 agent can get water.
    # This implies high competition.

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Collect yesterday's bids from all alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Calculate highest yesterday's bid
    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # --- Bidding Strategy ---
    bid = 0.0

    # Phase 1: Extreme Desperation (My HP is critically low)
    if my_hp <= 2:
        # If it's the last day, bid everything
        if current_day == EPISODE_DAYS:
            bid = my_budget
        else:
            # Bid very aggressively to ensure survival
            aggressive_bid_base = DAILY_SALARY * 1.05 # Slightly more than salary to outbid others

            if highest_prev_bid > 0:
                bid = max(aggressive_bid_base, highest_prev_bid + 5.0)
            else:
                bid = aggressive_bid_base

            # If truly desperate (HP=1), bid even higher if budget allows
            if my_hp == 1:
                 bid = max(bid, DAILY_SALARY * 1.5)

    # Phase 2: Moderate Desperation (My HP is getting low)
    elif my_hp <= 4:
        # Aim to win, but with slightly less aggression than extreme desperation
        moderate_bid_base = DAILY_SALARY * 0.8

        if highest_prev_bid > 0:
            bid = max(moderate_bid_base, highest_prev_bid + 2.0)
        else:
            bid = moderate_bid_base

    # Phase 3: Comfortable HP (My HP is good)
    else:
        # Try to win if possible without overspending, conserve budget

        # If no opponents are alive, bid minimum to win
        if not alive_opponents:
            bid = DAILY_SALARY * 0.1 # Very low bid to conserve if no competition
        else:
            # Estimate a competitive bid
            competitive_bid_base = DAILY_SALARY * 0.6

            if highest_prev_bid > 0:
                bid = max(competitive_bid_base, highest_prev_bid + 1.0)
            else:
                bid = competitive_bid_base

            # If budget is very high and HP is good, be slightly more competitive
            if my_budget > DAILY_SALARY * 3 and my_hp > 6:
                bid = max(bid, DAILY_SALARY * 0.7)

    # Ensure bid does not exceed current budget and is non-negative
    final_bid = min(my_budget, bid)
    return max(0.0, final_bid)

